params.command:
$ErrorActionPreference='Stop'
$repo='C:\\Users\\Xxkan\\mhw-mods-work-canonical'
$wt='C:\\Users\\Xxkan\\AppData\\Local\\Temp\\hcp-baseline-1128-a1'
Set-Location $repo
git fetch origin main
if(Test-Path $wt){ git worktree remove --force $wt | Out-Null; Remove-Item -Recurse -Force $wt -ErrorAction SilentlyContinue }
git worktree add --detach $wt origin/main
try {
  Set-Location $wt
  $sha=(git rev-parse HEAD | Out-String).Trim()
  python plugins/heaven-control-plane/verify.py
  if($LASTEXITCODE -ne 0){ throw 'control-plane verify failed' }
  python -m compileall -q plugins/heaven-control-plane/heaven_control_plane plugins/heaven-control-plane/tests plugins/heaven-control-plane/verify.py
  if($LASTEXITCODE -ne 0){ throw 'compileall failed' }
  [ordered]@{status='pass';sha=$sha}|ConvertTo-Json -Compress
} finally { Set-Location $repo; git worktree remove --force $wt | Out-Null }
